import React from 'react'
import { FormattedMessage } from 'react-intl'

import { IconPortal, IconForm, IconVerified, IconMoney } from './icons'

const ICONS = {
  portal: IconPortal,
  form: IconForm,
  verification: IconVerified,
  disbursement: IconMoney
}

const ClaimProcess = (props) => {
  return (
    <section className='claim__process-section'>
      <h1 className='claim__process-section--heading'>
        <FormattedMessage
          id='<span>Langkah Mudah Untuk</span> Klaim'
          values={{
            span: c => <span className='claim__theme-color'>{c}</span>
          }}
        />
      </h1>
      <div className='claim__flex-container'>
        {
          props.steps.process.map((d, index) => {
            const StepIcon = ICONS[d.key]
            return (
              <div className='claim__steps--card' key={d.key}>
                <span className='claim__steps--badge'>{index + 1}</span>
                <div className='claim__steps--icon'>
                  <StepIcon />
                </div>
                <h3 className='claim__steps--title'>
                  <FormattedMessage id={d.title} />
                </h3>
                <p className='claim__steps--text'>
                  <FormattedMessage id={d.description} />
                </p>
              </div>
            )
          })
        }
      </div>
    </section>
  )
}

export default ClaimProcess
