import React from 'react'
import { FormattedMessage } from 'react-intl'

import PortalWrapper from './index.style'

const KlaimPortal = (props) => {
  return (
    <PortalWrapper>
      <section className='portal__container'>
        {
          props.content.blocks.map(b => (
            <div
              className={'portal__row' + (b.imagePosition === 'left' ? ' portal__row--reverse' : '')}
              key={b.key}
            >
              <div className='portal__text'>
                <h2 className='portal__heading'>
                  <FormattedMessage id={b.heading} />
                </h2>
                <p className='portal__body'>
                  <FormattedMessage id={b.body} />
                </p>
              </div>
              <div className='portal__image'>
                <img src={b.img} alt='' />
              </div>
            </div>
          ))
        }
        <div className='portal__cta-container'>
          <a
            className='portal__cta'
            href={process.env.REACT_APP_POLICIES_LINK}
            target='_blank'
            rel='noopener noreferrer'
          >
            <FormattedMessage id={props.content.cta} />
          </a>
        </div>
      </section>
    </PortalWrapper>
  )
}

export default KlaimPortal
